        const method = buffer.readUInt16LE(idx + 8);
        const compSize = buffer.readUInt32LE(idx + 18);
        const fnameLen = buffer.readUInt16LE(idx + 26);
        const extraLen = buffer.readUInt16LE(idx + 28);
