  const suites = Array.isArray(testsuites.testsuite) ? testsuites.testsuite : [testsuites.testsuite];
  const results = [];
  for (const s of suites) {
    const cases = s.testcase ? (Array.isArray(s.testcase) ? s.testcase : [s.testcase]) : [];
