		return 0;
	}
	const res = cp.spawnSync('npx', ['jest', 'tests/session-history-ui.spec.js', '--runInBand', '--colors=false'], { stdio: 'inherit' });
	const status = res.status === null ? 1 : res.status;
	return status;
}

